import ast
import pathlib
import sys

ROOT = pathlib.Path(__file__).parent
API = ROOT / "api"
sys.path.insert(0, str(API))


def load_schemas(path, prefix):
    tree = ast.parse(path.read_text())
    out = {}
    for node in tree.body:
        if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name):
            name = node.targets[0].id
            if name.startswith(prefix) and name.endswith("_JSON"):
                out[name] = ast.literal_eval(node.value)
    return out


def params_of(path, func_name):
    tree = ast.parse(path.read_text())
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and node.name == func_name:
            return {a.arg for a in node.args.args + node.args.kwonlyargs}
    raise AssertionError(f"{func_name} not found in {path.name}")


